sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float radius;
uniform float angle;

half4 main(float2 coord) {
    float2 centerPixels = center * size;
    float2 delta = coord - centerPixels;
    float dist = length(delta);
    float radiusPixels = radius * min(size.x, size.y);

    if (dist > radiusPixels) {
        half4 color = image.eval(coord);
        if (color.a <= 0.0) {
            return half4(0.0);
        }
        half3 rgb = color.rgb / color.a;
        return half4(rgb * color.a, color.a);
    }

    float t = 1.0 - smoothstep(0.0, radiusPixels, dist);
    float rotation = angle * t;
    float s = sin(radians(rotation));
    float c = cos(radians(rotation));

    float2x2 mat = float2x2(c, -s, s, c);
    float2 rotated = mat * delta;
    float2 sampleCoord = centerPixels + rotated;

    half4 color = image.eval(sampleCoord);
    if (color.a <= 0.001) {
        return half4(0.0);
    }
    half3 rgb = color.rgb / color.a;
    return half4(rgb * color.a, color.a);
}
